static void rs485Poll() {
  while (RS.available()) {
    char c = (char)RS.read();
    if (c == '\n') {
      rxbuf[rxpos] = 0;
      if (rxpos > 0) handleLine(rxbuf);
      rxpos = 0;
    } else if (c != '\r') {
      if (rxpos < sizeof(rxbuf) - 1) {
        rxbuf[rxpos++] = c;
      } else {
