static void brightnessPreview(Adafruit_NeoPixel &strip, bool isBorder) {
  stopHitBlink();
  const uint32_t col = strip.Color(255,255,255);
  auto setGroup = [&](uint8_t group, uint32_t c) {
    if (group < 1 || group > 36) return;
